import{_ as o,o as r,c as a,a5 as l}from"./chunks/framework.Cooo9kuv.js";const b=JSON.parse('{"title":"WordPress 安全隐身插件 — NoWP Tools","description":"","frontmatter":{"标题":"WordPress 安全隐身插件 — NoWP Tools","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["Feed禁用","HTTP头清理","REST API","WordPress","XML-RPC","去品牌化","安全插件","指纹隐藏","文件防护","登录安全"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"模块一：前台 HTML 头部清理","slug":"模块一-前台-html-头部清理","link":"#模块一-前台-html-头部清理","children":[]},{"level":3,"title":"模块二：后台特征清理","slug":"模块二-后台特征清理","link":"#模块二-后台特征清理","children":[]},{"level":3,"title":"模块三：Feed 禁用","slug":"模块三-feed-禁用","link":"#模块三-feed-禁用","children":[]},{"level":3,"title":"模块四：API 与 XML-RPC 控制","slug":"模块四-api-与-xml-rpc-控制","link":"#模块四-api-与-xml-rpc-控制","children":[]},{"level":3,"title":"模块五：版本号隐藏","slug":"模块五-版本号隐藏","link":"#模块五-版本号隐藏","children":[]},{"level":3,"title":"模块六：HTTP 头清理","slug":"模块六-http-头清理","link":"#模块六-http-头清理","children":[]},{"level":3,"title":"模块七：目录路径隐藏","slug":"模块七-目录路径隐藏","link":"#模块七-目录路径隐藏","children":[]},{"level":3,"title":"模块八：登录安全","slug":"模块八-登录安全","link":"#模块八-登录安全","children":[]},{"level":3,"title":"模块九：文件暴露防护","slug":"模块九-文件暴露防护","link":"#模块九-文件暴露防护","children":[]},{"level":3,"title":"模块十：深层指纹清理","slug":"模块十-深层指纹清理","link":"#模块十-深层指纹清理","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置防护模块","slug":"第二步-配置防护模块","link":"#第二步-配置防护模块","children":[]},{"level":3,"title":"第三步：查看安全诊断","slug":"第三步-查看安全诊断","link":"#第三步-查看安全诊断","children":[]},{"level":3,"title":"第四步：保存并验证","slug":"第四步-保存并验证","link":"#第四步-保存并验证","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07）","slug":"v1-0-0-2026-07","link":"#v1-0-0-2026-07","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 安全隐身插件 — NoWP Tools.md","filePath":"md/wordpress主题插件/WordPress 安全隐身插件 — NoWP Tools.md"}'),d={name:"md/wordpress主题插件/WordPress 安全隐身插件 — NoWP Tools.md"};function t(s,e,c,n,i,p){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="wordpress-安全隐身插件-—-nowp-tools" tabindex="-1">WordPress 安全隐身插件 — NoWP Tools <a class="header-anchor" href="#wordpress-安全隐身插件-—-nowp-tools" aria-label="Permalink to &quot;WordPress 安全隐身插件 — NoWP Tools&quot;">​</a></h1><blockquote><p>从扫描器视角全面隐藏 WordPress 程序特征，清理 HTML 头部特征标签、禁用 Feed 订阅源、控制 REST API 与 XML-RPC 访问、隐藏版本号、清理 HTTP 响应头、重命名目录路径、加固登录安全、防护敏感文件暴露、清理深层指纹，一站式降低网站被识别为 WordPress 站点的风险。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/88c38657-f42f-4fc6-b857-8eb4f3c3a74a.png" alt=""></p><p>NoWP Tools 是一款 WordPress 安全隐身插件，从攻击者与扫描器的视角出发，系统性地隐藏网站作为 WordPress 站点的各类程序特征。</p><p>插件将 10 大防护模块整合于一个统一的后台管理界面，每个模块均配有独立总开关和数十项精细化子开关。开启后，插件在 PHP 层自动执行各项隐藏操作，无需修改主题或服务器配置即可生效。同时内置安全诊断面板，可实时检测网站是否存在敏感文件暴露风险，并提供 Apache / Nginx 服务器加固配置指引和 wp-config.php 安全建议。</p><p>与传统的安全插件不同，NoWP Tools 侧重于「隐藏身份」而非「修补漏洞」——通过移除 WordPress 在 HTML 源码、HTTP 响应头、CSS 类名、URL 参数等各处遗留的指纹特征，大幅降低自动化扫描工具识别和定向攻击的成功率。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="模块一-前台-html-头部清理" tabindex="-1">模块一：前台 HTML 头部清理 <a class="header-anchor" href="#模块一-前台-html-头部清理" aria-label="Permalink to &quot;模块一：前台 HTML 头部清理&quot;">​</a></h3><p>清理 WordPress 自动注入到前台页面 <code>&lt;head&gt;</code> 区域的各种特征标签和资源引用，共 11 项子开关：</p><p>— 移除 <code>wp_generator</code> 元标签，扫描器无法在源码中看到 WP 版本号；<br> — 移除前台和后台的 <code>wlwmanifest</code> 链接，去除 Windows Live Writer 支持标识；<br> — 移除 <code>rsd_link</code>（Really Simple Discovery）服务发现链接；<br> — 移除 <code>feed_links</code> 及其扩展链接，浏览器不再显示 RSS 图标，RSS 阅读器无法自动发现 Feed；<br> — 移除 <code>rest_output_link</code>，源码中不暴露 <code>/wp-json/</code> 端点路径；<br> — 移除 oEmbed 发现链接，外部站点嵌入本站内容时无法自动发现；<br> — 移除 <code>shortlink</code> 短链接 rel 标签；<br> — 移除前后文章导航链接（<code>adjacent_posts_rel_link</code>），浏览器预加载功能可能受影响；<br> — 移除 DNS 预取资源提示（<code>resource_hints</code>）；<br> — 移除 WordPress 内置 Emoji 兼容脚本和样式，现代浏览器不受影响。</p><h3 id="模块二-后台特征清理" tabindex="-1">模块二：后台特征清理 <a class="header-anchor" href="#模块二-后台特征清理" aria-label="Permalink to &quot;模块二：后台特征清理&quot;">​</a></h3><p>隐藏 WordPress 后台管理区域中的品牌标识和特征元素，共 5 项子开关：</p><p>— 清理后台页脚「感谢使用 WordPress 创作」文字及版本号信息；<br> — 清理后台页面浏览器标题栏中的「WordPress」字样；<br> — 移除仪表盘中的 WordPress 官方新闻和活动小部件；<br> — 移除管理栏左侧的 WordPress Logo 及其子菜单；<br> — 未登录用户访问 <code>/wp-admin/</code> 时返回 404 状态，扫描器无法探测后台地址。</p><h3 id="模块三-feed-禁用" tabindex="-1">模块三：Feed 禁用 <a class="header-anchor" href="#模块三-feed-禁用" aria-label="Permalink to &quot;模块三：Feed 禁用&quot;">​</a></h3><p>彻底禁用 WordPress 的 RSS/Atom 订阅源功能，共 5 项子开关：</p><p>— 分别禁用 RSS2、Atom、RDF 三种 Feed 格式输出；<br> — 禁用评论 Feed 订阅；<br> — 所有 Feed 请求 301 重定向到网站首页，避免暴露站点结构。</p><h3 id="模块四-api-与-xml-rpc-控制" tabindex="-1">模块四：API 与 XML-RPC 控制 <a class="header-anchor" href="#模块四-api-与-xml-rpc-控制" aria-label="Permalink to &quot;模块四：API 与 XML-RPC 控制&quot;">​</a></h3><p>控制 REST API 访问权限，禁用 XML-RPC 远程调用和 Trackback 引用通知，共 6 项子开关：</p><p>— 未登录用户访问 REST API 时返回 401 未授权状态码，已登录管理员不受影响；<br> — 从 HTTP 响应头中移除 REST API 的 Link 头；<br> — 完全禁用 XML-RPC 远程发布接口，关闭 <code>xmlrpc_enabled</code>；<br> — 直接访问 <code>xmlrpc.php</code> 时返回 403 禁止访问，防止 XML-RPC 暴力攻击；<br> — 禁用 Trackback 和 Pingback 引用通知功能，减少垃圾引用；<br> — 用自定义内容替换 WordPress 默认的 <code>robots.txt</code>，不暴露后台和 Feed 路径。</p><h3 id="模块五-版本号隐藏" tabindex="-1">模块五：版本号隐藏 <a class="header-anchor" href="#模块五-版本号隐藏" aria-label="Permalink to &quot;模块五：版本号隐藏&quot;">​</a></h3><p>从所有输出中彻底移除 WordPress 版本号，共 2 项子开关：</p><p>— 过滤 <code>the_generator</code> 函数始终返回空字符串，所有通过该函数输出的版本信息被隐藏；<br> — 移除 CSS 和 JS 文件 URL 中的 <code>?ver=X.X.X</code> 查询参数，更新插件或主题后用户可能加载旧版缓存资源。</p><h3 id="模块六-http-头清理" tabindex="-1">模块六：HTTP 头清理 <a class="header-anchor" href="#模块六-http-头清理" aria-label="Permalink to &quot;模块六：HTTP 头清理&quot;">​</a></h3><p>清理服务器 HTTP 响应头中的 WordPress 相关字段，共 3 项子开关：</p><p>— 移除 <code>X-Pingback</code> 响应头，扫描器无法通过 HTTP 头发现 <code>xmlrpc.php</code> 地址；<br> — 移除 <code>X-Powered-By</code> 响应头，PHP 以模块模式运行时可能需配合服务器配置；<br> — 移除 <code>Link</code> 响应头中的 REST API 和 shortlink 等 WordPress 特有信息。</p><h3 id="模块七-目录路径隐藏" tabindex="-1">模块七：目录路径隐藏 <a class="header-anchor" href="#模块七-目录路径隐藏" aria-label="Permalink to &quot;模块七：目录路径隐藏&quot;">​</a></h3><p>隐藏网站的目录结构，防止用户枚举和路径探测，支持自定义登录入口：</p><p>— 阻止用户枚举攻击：对 <code>?author=N</code> 格式的请求自动 301 重定向到首页，攻击者无法通过遍历作者 ID 收集用户名；<br> — 自定义登录 URL：将默认的 <code>/wp-login.php</code> 替换为自定义路径（如 <code>/signin</code>），需配合服务器 URL 重写规则生效，请勿使用常见路径。</p><h3 id="模块八-登录安全" tabindex="-1">模块八：登录安全 <a class="header-anchor" href="#模块八-登录安全" aria-label="Permalink to &quot;模块八：登录安全&quot;">​</a></h3><p>登录页面去品牌化，统一错误信息防止用户名枚举，共 5 项子开关：</p><p>— 登录页 Logo 链接指向网站首页而非 wordpress.org；<br> — 隐藏登录页面 WordPress Logo 图标，替换为网站名称文字；<br> — 隐藏登录页语言切换下拉菜单；<br> — 统一登录错误信息：无论用户名不存在还是密码错误，均显示相同的提示信息，攻击者无法判断用户名是否存在；<br> — 防止密码重置枚举：不存在的用户执行密码重置时仍然显示「邮件已发送」提示，且不存在的用户 ID 禁止密码重置流程。</p><h3 id="模块九-文件暴露防护" tabindex="-1">模块九：文件暴露防护 <a class="header-anchor" href="#模块九-文件暴露防护" aria-label="Permalink to &quot;模块九：文件暴露防护&quot;">​</a></h3><p>拦截对 WordPress 敏感文件的直接访问，并提供安全诊断功能：</p><p>— 拦截敏感文件访问：对 <code>wp-config.php</code>、<code>readme.html</code>、<code>license.txt</code> 等文件直接访问返回 404，不影响后台正常功能；<br> — 安全诊断面板：后台实时检测 <code>readme.html</code>、<code>license.txt</code>、<code>wp-config-sample.php</code>、<code>debug.log</code> 等文件是否存在，给出加固建议。</p><h3 id="模块十-深层指纹清理" tabindex="-1">模块十：深层指纹清理 <a class="header-anchor" href="#模块十-深层指纹清理" aria-label="Permalink to &quot;模块十：深层指纹清理&quot;">​</a></h3><p>移除 WordPress 更深层次的指纹特征，共 8 项子开关：</p><p>— 拦截 <code>wp-cron.php</code> 直接访问，需配合服务器真实 cron 替代，否则定时任务会失效；<br> — 清理 <code>body_class</code> 中的 <code>wp-embed-responsive</code>、<code>wp-custom-logo</code> 等 WP 特征类名；<br> — 清理 <code>post_class</code> 中的 <code>hentry</code>、<code>type-post</code>、<code>type-page</code>、<code>status-publish</code>、<code>format-standard</code> 等类名；<br> — 清理导航菜单 CSS 类名中的 <code>menu-item-type-post_type</code>、<code>menu-item-type-custom</code> 等特征类名及菜单项 ID；<br> — 自定义搜索 URL 参数：将默认的 <code>?s=</code> 替换为自定义参数（如 <code>?search=</code>），主题中的搜索表单可能需要相应修改；<br> — 完全禁用评论系统：移除后台评论菜单、小部件和管理栏评论入口，前台不显示已有评论；<br> — 伪装 wp-json 根路径：未登录用户访问 <code>/wp-json/</code> 根路径时返回 404；<br> — 拦截 <code>wp-signup.php</code>、<code>wp-activate.php</code>、<code>wp-mail.php</code> 等多站点模式文件的直接访问。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>nowp_tools</code> 文件夹上传至网站 <code>wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「NoWP Tools」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-26-scaled.png" alt=""></p><h3 id="第二步-配置防护模块" tabindex="-1">第二步：配置防护模块 <a class="header-anchor" href="#第二步-配置防护模块" aria-label="Permalink to &quot;第二步：配置防护模块&quot;">​</a></h3><p>进入后台「NoWP Tools」管理页面：</p><p>— 页面顶部可切换界面语言（自动 / 中文 / English），切换后即时生效，不影响已保存的配置；<br> — 10 个防护模块以卡片形式依次排列，每个模块卡片标题栏右侧设有总开关，点击即可启用或停用整组功能；<br> — 总开关启用后，卡片展开显示该模块下的所有子开关，每项子开关均配有功能名称和启用影响提示；<br> — 模块七「目录路径隐藏」和模块十「深层指纹清理」中的自定义路径 / 搜索参数功能，在启用对应开关后会显示文本输入框，支持自定义设置；<br> — 页面底部设有「服务器配置指引」卡片，提供 Apache .htaccess、Nginx 配置文件、wp-config.php 加固建议和 Cookie 前缀修改指引，可直接复制使用。</p><h3 id="第三步-查看安全诊断" tabindex="-1">第三步：查看安全诊断 <a class="header-anchor" href="#第三步-查看安全诊断" aria-label="Permalink to &quot;第三步：查看安全诊断&quot;">​</a></h3><p>如果模块九的「显示安全诊断面板」开关已启用，管理页面下方会展示当前网站的敏感文件检测结果：</p><p>— 绿色对勾表示文件不存在或已移除，安全；<br> — 黄色警告表示文件存在且可能被公开访问，建议按指引删除或配合服务器规则拦截。</p><h3 id="第四步-保存并验证" tabindex="-1">第四步：保存并验证 <a class="header-anchor" href="#第四步-保存并验证" aria-label="Permalink to &quot;第四步：保存并验证&quot;">​</a></h3><p>— 修改配置后点击页面底部「保存设置」按钮，页面刷新后显示保存成功提示；<br> — 访问网站前台，查看页面源码确认 <code>&lt;head&gt;</code> 区域中 WP 特征标签是否已清除；<br> — 使用 HTTP 头检测工具确认 <code>X-Pingback</code>、<code>Link</code> 等响应头是否已移除；<br> — 未登录状态下访问 <code>/wp-admin/</code>、<code>/wp-json/</code>、<code>/feed/</code> 等路径，验证是否返回正确的拦截状态。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件侧重于隐藏 WordPress 程序特征，并非漏洞修复工具，建议配合其他安全插件和服务器加固方案综合使用；<br> — 模块三「Feed 禁用」启用后，RSS 阅读器将无法订阅网站内容，适合不需要 RSS 功能的纯展示型网站；<br> — 模块四启用「禁用 REST API（未登录）」后，外部应用和移动端 App 可能无法通过 API 读取站点数据，Jetpack 等依赖 REST API 的插件会受影响；<br> — 模块五「移除 CSS/JS URL 中的 ?ver=」启用后，更新插件或主题时用户端可能因缓存加载旧版资源，更新后建议清除缓存；<br> — 模块七「自定义登录 URL」启用后，需在服务器端配置对应的 URL 重写规则（面板中已提供 Apache 和 Nginx 配置示例），如果忘记自定义登录路径将无法登录后台；<br> — 模块八「统一登录错误信息」启用后，合法用户在忘记密码时也无法区分用户名错误还是密码错误；<br> — 模块十「拦截 wp-cron.php」启用后必须配置服务器的真实 cron 定时任务替代 WP-Cron，否则定时发布等依赖功能会失效；<br> — 模块十中的 body_class / post_class / nav_menu 清理功能可能影响主题样式，启用前建议检查主题是否依赖这些 CSS 类名。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.top<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07" tabindex="-1">v1.0.0（2026-07） <a class="header-anchor" href="#v1-0-0-2026-07" aria-label="Permalink to &quot;v1.0.0（2026-07）&quot;">​</a></h3><p>— 首次发布，集成 10 大 WordPress 特征隐藏模块；<br> — 前台 HTML 头部清理：移除 wp_generator、wlwmanifest、rsd_link、feed_links、rest_output_link、oEmbed、shortlink、resource_hints、Emoji 等 11 项特征标签；<br> — 后台特征清理：隐藏页脚品牌、标题 WordPress 字样、仪表盘小部件、管理栏 Logo、未登录 404 保护；<br> — Feed 全面禁用：RSS2、Atom、RDF、评论 Feed 及 301 重定向到首页；<br> — REST API 与 XML-RPC 控制：未登录 401 拦截、禁用 XML-RPC、拦截 xmlrpc.php、禁用 Trackback/Pingback、自定义 robots.txt；<br> — 版本号隐藏：过滤 the_generator、移除 CSS/JS URL 中的 ?ver= 参数；<br> — HTTP 头清理：移除 X-Pingback、X-Powered-By、Link 响应头；<br> — 目录路径隐藏：阻止用户枚举、自定义登录 URL；<br> — 登录安全加固：修改 Logo 链接、隐藏 WP Logo、隐藏语言切换器、统一错误信息、防密码重置枚举；<br> — 文件暴露防护：拦截敏感文件访问、内置安全诊断面板；<br> — 深层指纹清理：拦截 wp-cron.php、清理 body_class/post_class/nav_menu CSS 类名、自定义搜索参数、禁用评论系统、伪装 wp-json、拦截多站点文件；<br> — 内置 Apache / Nginx 服务器配置指引和 wp-config.php 加固建议；<br> — 支持界面语言切换（自动 / 中文 / English）。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3034.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3034.html</a></p>',60)])])}const P=o(d,[["render",t]]);export{b as __pageData,P as default};
